CREATE OR REPLACE FUNCTION device_platform.check_admin_coverage()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'device_platform'
AS $function$
DECLARE org_id uuid; affected_user uuid;
BEGIN
  IF TG_TABLE_NAME = 'users' THEN
    IF TG_OP <> 'INSERT' THEN
      IF OLD.platform_role = 'platform_admin' AND OLD.is_active
        AND NOT EXISTS (SELECT 1 FROM device_platform.users WHERE platform_role = 'platform_admin' AND is_active) THEN
        RAISE EXCEPTION 'Cannot remove the last active platform administrator' USING ERRCODE = '23514';
      END IF;
    END IF;
    affected_user := CASE WHEN TG_OP = 'DELETE' THEN OLD.id ELSE NEW.id END;
    FOR org_id IN SELECT DISTINCT organization_id FROM device_platform.organization_memberships
      WHERE user_id = affected_user AND role = 'org_admin' ORDER BY organization_id LOOP
      PERFORM device_platform.check_org_admin(org_id);
    END LOOP;
  ELSIF TG_TABLE_NAME = 'organizations' THEN
    PERFORM device_platform.check_org_admin(CASE WHEN TG_OP = 'DELETE' THEN OLD.id ELSE NEW.id END);
  ELSE
    PERFORM device_platform.check_org_admin(CASE WHEN TG_OP = 'DELETE' THEN OLD.organization_id ELSE NEW.organization_id END);
  END IF;
  RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION device_platform.connection_version()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'device_platform'
AS $function$
BEGIN
  IF ROW(NEW.provider, NEW.connection_type, NEW.auth_mode, NEW.settings, NEW.secret_ref)
    IS DISTINCT FROM ROW(OLD.provider, OLD.connection_type, OLD.auth_mode, OLD.settings, OLD.secret_ref) THEN
    NEW.configuration_version := OLD.configuration_version + 1;
    NEW.validation_results := '{}'::jsonb;
    NEW.last_validated_at := NULL;
  ELSIF NEW.configuration_version IS DISTINCT FROM OLD.configuration_version THEN
    RAISE EXCEPTION 'Connection version is maintained by the database' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION device_platform.credential_version()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'device_platform'
AS $function$
BEGIN
  IF NEW.credential_hash IS DISTINCT FROM OLD.credential_hash
    OR NEW.credential_revoked_at IS DISTINCT FROM OLD.credential_revoked_at THEN
    NEW.credential_version := OLD.credential_version + 1;
    IF NEW.credential_hash IS NOT NULL THEN
      NEW.credential_issued_at := clock_timestamp();
    ELSIF OLD.credential_hash IS NOT NULL THEN
      NEW.credential_revoked_at := clock_timestamp();
    END IF;
  ELSIF NEW.credential_version IS DISTINCT FROM OLD.credential_version THEN
    RAISE EXCEPTION 'Credential version changes only on issuance/rotation/revocation' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION device_platform.lock_admin_changes()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'device_platform'
AS $function$
BEGIN
  IF current_setting('transaction_isolation') <> 'read committed' THEN
    RAISE EXCEPTION 'Administrator mutations require READ COMMITTED transactions' USING ERRCODE = '25000';
  END IF;
  PERFORM id FROM device_platform.platform_settings WHERE id = 1 FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Platform singleton must be initialized first'; END IF;
  RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION device_platform.maintain_platform_settings()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'device_platform'
AS $function$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'Cannot delete the platform settings singleton' USING ERRCODE = '23514';
  END IF;
  IF NEW.id IS DISTINCT FROM OLD.id OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN
    RAISE EXCEPTION 'Platform settings identity is immutable' USING ERRCODE = '23514';
  END IF;
  IF NEW.updated_by IS NULL OR NOT EXISTS (SELECT 1 FROM device_platform.users
    WHERE id = NEW.updated_by AND is_active AND platform_role = 'platform_admin') THEN
    RAISE EXCEPTION 'Settings changes require an active platform administrator' USING ERRCODE = '23514';
  END IF;
  NEW.configuration_version := OLD.configuration_version + 1;
  NEW.updated_at := clock_timestamp();
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION device_platform.policy_within(candidate jsonb, limits jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE PARALLEL SAFE
AS $function$
DECLARE entry record;
BEGIN
  IF jsonb_typeof(candidate) IS DISTINCT FROM 'object'
    OR jsonb_typeof(limits) IS DISTINCT FROM 'object' THEN RETURN false; END IF;
  FOR entry IN SELECT * FROM jsonb_each(limits) LOOP
    IF NOT candidate ? entry.key THEN RETURN false; END IF;
    IF jsonb_typeof(entry.value) = 'object' THEN
      IF NOT device_platform.policy_within(candidate->entry.key, entry.value) THEN RETURN false; END IF;
    ELSIF jsonb_typeof(candidate->entry.key) IS DISTINCT FROM 'number' THEN RETURN false;
    ELSIF (candidate->>entry.key)::numeric > entry.value::text::numeric THEN RETURN false;
    END IF;
  END LOOP;
  RETURN true;
END $function$

CREATE OR REPLACE FUNCTION device_platform.protect_context()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'device_platform'
AS $function$
DECLARE key text;
BEGIN
  FOREACH key IN ARRAY TG_ARGV LOOP
    IF to_jsonb(NEW)->key IS DISTINCT FROM to_jsonb(OLD)->key THEN
      RAISE EXCEPTION '%: immutable context field %', TG_TABLE_NAME, key USING ERRCODE = '23514';
    END IF;
  END LOOP;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION device_platform.protect_history()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'device_platform'
AS $function$
BEGIN
  IF TG_OP = 'UPDATE' THEN
    RAISE EXCEPTION '% is append-only', TG_TABLE_NAME USING ERRCODE = '23514';
  END IF;
  IF OLD.expires_at > clock_timestamp() THEN
    RAISE EXCEPTION '% retention has not expired', TG_TABLE_NAME USING ERRCODE = '23514';
  END IF;
  RETURN OLD;
END $function$

CREATE OR REPLACE FUNCTION device_platform.touch_record()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'device_platform'
AS $function$
BEGIN
  NEW.updated_at := clock_timestamp();
  IF to_jsonb(NEW) ? 'is_active' THEN
    IF NEW.is_active IS DISTINCT FROM OLD.is_active THEN
      NEW.status_changed_at := NEW.updated_at;
    ELSE
      NEW.status_changed_at := OLD.status_changed_at;
    END IF;
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION device_platform.valid_device_defaults(value jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE PARALLEL SAFE
AS $function$
DECLARE k text;
BEGIN
  IF jsonb_typeof(value) IS DISTINCT FROM 'object' THEN RETURN false; END IF;
  FOREACH k IN ARRAY ARRAY['heartbeat_seconds','offline_after_seconds','active_poll_seconds','telemetry_sample_seconds'] LOOP
    IF NOT device_platform.positive_integer(value->k) THEN RETURN false; END IF;
  END LOOP;
  RETURN (value->>'offline_after_seconds')::numeric > (value->>'heartbeat_seconds')::numeric;
END $function$

CREATE OR REPLACE FUNCTION device_platform.valid_metrics(value jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE PARALLEL SAFE
AS $function$
DECLARE k text; v jsonb;
BEGIN
  IF jsonb_typeof(value) IS DISTINCT FROM 'object' THEN RETURN false; END IF;
  FOREACH k IN ARRAY ARRAY['cpu_percent','memory_percent','disk_free_bytes','temperature_c',
    'uptime_seconds','capture_fps','dropped_video_frames','audio_overflows','audio_underflows',
    'processing_latency_ms','upload_failures','pending_runs'] LOOP
    v := value->k;
    IF v IS NULL OR v = 'null'::jsonb THEN CONTINUE; END IF;
    IF jsonb_typeof(v) <> 'number' THEN RETURN false; END IF;
    IF k <> 'temperature_c' AND v::text::numeric < 0 THEN RETURN false; END IF;
    IF k IN ('cpu_percent','memory_percent') AND v::text::numeric > 100 THEN RETURN false; END IF;
  END LOOP;
  FOREACH k IN ARRAY ARRAY['camera_status','microphone_status','speaker_status'] LOOP
    v := value->k;
    IF v IS NULL OR v = 'null'::jsonb THEN CONTINUE; END IF;
    IF jsonb_typeof(v) <> 'string' OR value->>k NOT IN ('ready','busy','absent','error','unknown') THEN RETURN false; END IF;
  END LOOP;
  RETURN true;
END $function$

CREATE OR REPLACE FUNCTION device_platform.valid_policy(value jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE PARALLEL SAFE
AS $function$
DECLARE k text; section text; required_keys text[];
BEGIN
  IF jsonb_typeof(value) IS DISTINCT FROM 'object' THEN RETURN false; END IF;
  FOREACH k IN ARRAY ARRAY['offline_authorization_hours','media_retention_hours',
    'result_retention_days','telemetry_retention_days','operational_retention_days','audit_retention_days'] LOOP
    IF NOT device_platform.positive_integer(value->k) THEN RETURN false; END IF;
  END LOOP;
  FOREACH section IN ARRAY ARRAY['capture_limits','usage_limits'] LOOP
    IF jsonb_typeof(value->section) IS DISTINCT FROM 'object' THEN RETURN false; END IF;
    required_keys := CASE section WHEN 'capture_limits' THEN
      ARRAY['max_audio_seconds','max_video_seconds','max_width','max_height','max_fps','max_upload_bytes']
      ELSE ARRAY['max_concurrent_jobs','daily_audio_seconds','daily_video_seconds','daily_tts_characters'] END;
    FOREACH k IN ARRAY required_keys LOOP
      IF NOT device_platform.positive_integer(value->section->k) THEN RETURN false; END IF;
    END LOOP;
  END LOOP;
  RETURN true;
END $function$

CREATE OR REPLACE FUNCTION device_platform.valid_processing_settings(value jsonb, audio_connection uuid, video_connection uuid, output_connection uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE PARALLEL SAFE
AS $function$
DECLARE sections text[] := ARRAY['audio_input','video','audio_output'];
  bindings uuid[] := ARRAY[audio_connection,video_connection,output_connection];
  part jsonb; i integer;
BEGIN
  IF jsonb_typeof(value) IS DISTINCT FROM 'object' OR value->'schema_version' IS DISTINCT FROM '1'::jsonb THEN RETURN false; END IF;
  FOR i IN 1..3 LOOP
    part := value->sections[i];
    IF jsonb_typeof(part) IS DISTINCT FROM 'object'
      OR jsonb_typeof(part->'enabled') IS DISTINCT FROM 'boolean'
      OR part ? 'connection_id' THEN RETURN false; END IF;
    IF part->'enabled' = 'true'::jsonb THEN
      IF COALESCE(part->>'execution_mode','') NOT IN ('local','cloud')
        OR jsonb_typeof(part->'operation') IS DISTINCT FROM 'string'
        OR jsonb_typeof(part->'engine') IS DISTINCT FROM 'string'
        OR btrim(part->>'operation') = '' OR btrim(part->>'engine') = '' THEN RETURN false; END IF;
      IF (part->>'execution_mode' = 'cloud') <> (bindings[i] IS NOT NULL) THEN RETURN false; END IF;
    ELSIF bindings[i] IS NOT NULL THEN RETURN false;
    END IF;
  END LOOP;
  RETURN true;
END $function$
